'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];let currentTab='search',imageAsset=null,queryId='',metrics=null,authenticated=false,noticeTimer;
const labels={indexed:'已索引',pending:'等待中',preprocessing:'预处理中',encoding:'编码中',failed:'失败',cancelled:'已取消',image:'图片',video:'视频',pdf:'PDF 页面',text:'文字',joint:'图文'};
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#toast').hidden=true,6500)}
async function api(path,body){const r=await fetch('/api/'+path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});let j;try{j=await r.json()}catch{throw Error('服务器返回格式异常')}if(!r.ok){if(r.status===401){authenticated=false;$('#login').hidden=false;$('#workspace').hidden=true}throw Error(j.detail||r.statusText)}return j}
async function guarded(fn){try{await fn()}catch(e){toast(e.message)}}
function tab(name){currentTab=name;$$('.tab').forEach(n=>n.hidden=n.id!==name);$$('nav button').forEach(n=>n.classList.toggle('active',n.dataset.tab===name));if(authenticated){if(name==='data')guarded(loadAssets);if(name==='eval')guarded(loadEval)}}
$$('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));
async function enter(){authenticated=true;$('#login').hidden=true;$('#workspace').hidden=false;await datasets();await status();tab(currentTab)}
$('#loginForm').onsubmit=e=>{e.preventDefault();guarded(async()=>{await api('login',{password:$('#password').value});$('#password').value='';await enter()})};
async function datasets(selected){const ds=await api('datasets');$$('.dataset').forEach(s=>{const old=selected||s.value||(s.id==='searchDataset'?'demo':'personal');s.replaceChildren(...ds.filter(d=>d.id!=='queries').map(d=>{const o=el('option',d.name);o.value=d.id;return o}));s.value=old})}
async function status(){const s=await api('status');$('#health').textContent=s.state==='ready'?'● 模型就绪':s.state==='loading'?'模型加载中':s.state;$('#modelStatus').textContent=`${s.model} · ${s.precision} · ${s.dimension} 维 · ${s.units} 个单元 · ${s.offload?'CPU offload':'单 GPU'}${s.error?' · '+s.error:''}`;$('#runtimeDetails').textContent=JSON.stringify({状态:s.state,输入档位:s.profile,输入上限:s.limits,原生视频:s.native_video,冷加载秒:s.cold_load_s,队列:s.queue,正在处理:s.busy_asset,文件状态:s.counts,GPU显存MiB:s.gpu,索引指纹:s.fingerprint},null,2);return s}
function xhrUpload(file,dataset,name,onprogress){return new Promise((resolve,reject)=>{const x=new XMLHttpRequest();x.open('POST','/api/upload?dataset='+encodeURIComponent(dataset)+'&name='+encodeURIComponent(name));x.upload.onprogress=e=>{if(e.lengthComputable)onprogress(Math.round(e.loaded/e.total*100))};x.onload=()=>{let j;try{j=JSON.parse(x.responseText)}catch{reject(Error('上传响应异常'));return}x.status<300?resolve(j):reject(Error(j.detail||'上传失败'))};x.onerror=()=>reject(Error('上传网络中断，可重新选择文件重试'));x.send(file)})}
async function upload(files,dataset){let done=0,fail=0,duplicates=0;for(const f of files){const name=f.webkitRelativePath||f.relativePath||f.name;try{const r=await xhrUpload(f,dataset,name,p=>$('#uploadProgress').textContent=`${done+fail+1}/${files.length} · ${name} · ${p}%`);if(r.duplicate)duplicates++;done++}catch(e){fail++;toast(name+'：'+e.message)}}$('#uploadProgress').textContent=`上传完成：${done} 成功，${duplicates} 内容重复，${fail} 失败。正在后台处理。`;await loadAssets()}
$('#files').onchange=e=>guarded(()=>upload([...e.target.files],$('#dataDataset').value));$('#folder').onchange=e=>guarded(()=>upload([...e.target.files],$('#dataDataset').value));
const drop=$('#drop');drop.ondragover=e=>{e.preventDefault();drop.classList.add('over')};drop.ondragleave=()=>drop.classList.remove('over');
async function walk(entry,prefix=''){if(entry.isFile)return new Promise((res,rej)=>entry.file(f=>{Object.defineProperty(f,'relativePath',{value:prefix+f.name});res([f])},rej));if(entry.isDirectory){const reader=entry.createReader();let all=[],part;do{part=await new Promise((res,rej)=>reader.readEntries(res,rej));all.push(...part)}while(part.length);return(await Promise.all(all.map(x=>walk(x,prefix+entry.name+'/')))).flat()}return[]}
drop.ondrop=e=>{e.preventDefault();drop.classList.remove('over');const entries=[...e.dataTransfer.items].map(x=>x.webkitGetAsEntry?.()).filter(Boolean),fallback=[...e.dataTransfer.files];guarded(async()=>upload(entries.length?(await Promise.all(entries.map(x=>walk(x)))).flat():fallback,$('#dataDataset').value))};
$('#queryFile').onchange=e=>guarded(async()=>{const f=e.target.files[0];if(!f)return;$('#searchButton').disabled=true;try{$('#queryImageName').textContent='上传查询图片…';const r=await xhrUpload(f,'queries',f.name,p=>$('#queryImageName').textContent=`上传 ${p}%`);imageAsset=r.asset;for(let i=0;i<180;i++){const a=(await api('assets?dataset=queries')).find(x=>x.id===r.asset);if(a?.status==='indexed'){$('#queryImageName').textContent=f.name;return}if(a?.status==='failed')throw Error(a.error);await new Promise(r=>setTimeout(r,1000))}throw Error('图片仍在处理，请稍后重试')}finally{$('#searchButton').disabled=false}});
$('#clearImage').onclick=()=>{imageAsset=null;$('#queryFile').value='';$('#queryImageName').textContent='可与文字联合查询'};
function metaText(h){const m=h.meta;return m.page?'第 '+m.page+' 页':m.start!==undefined?`${m.start.toFixed(1)}–${m.end.toFixed(1)} 秒`:m.start_seconds!==undefined?`${m.start_seconds}–${m.end_seconds} 秒`:labels[h.kind]||h.kind}
function card(h,qid=queryId){const c=el('button',undefined,'card');c.type='button';if(h.thumbnail){const img=el('img');img.src=h.thumbnail;img.alt=h.name;img.loading='lazy';c.append(img)}else{const t=el('div',h.meta.text||h.meta.preview||'文字片段 · 点击阅读','textpreview');c.append(t);fetch(h.content).then(r=>r.text()).then(s=>t.textContent=s.slice(0,350)).catch(()=>{})}const b=el('div',undefined,'body');b.append(el('div',h.name,'name'));const score=el('div',undefined,'score');score.append(el('span',`${h.rank||''} · ${metaText(h)}`),el('span',h.score.toFixed(4)));b.append(score);if(h.judgment)b.append(el('div',h.judgment==='relevant'?'已标注相关':'未判定','small muted'));c.append(b);c.onclick=()=>guarded(()=>detail(h,qid));return c}
async function detail(h,qid){const b=$('#detailBody');b.replaceChildren(el('h2',h.name),el('p',`${metaText(h)} · 相似度 ${h.score.toFixed(6)}`,'muted'));if(h.kind==='text'){b.append(el('pre',await(await fetch(h.content)).text()))}else{const m=el(h.kind==='video'?'video':'img');m.src=h.content;if(h.kind==='video')m.controls=true;else m.alt=h.name;b.append(m)}const a=el('a','下载源文件 ↗');a.href='/api/assets/'+h.asset+'/original';b.append(a,el('p','SHA-256：'+h.asset,'small muted'));const annotation=el('div',undefined,'actions');for(const [label,title] of [['relevant','标为相关'],['irrelevant','标为不相关'],['unjudged','暂不判定']]){const x=el('button',title);x.onclick=()=>guarded(async()=>{await api('annotations',{query:qid,unit:h.id,label});toast('标注已单独保存，不修改冻结评测标签')});annotation.append(x)}b.append(annotation);const pd=el('details');pd.append(el('summary','预处理与片段信息'),el('pre',JSON.stringify(h.meta,null,2)));b.append(pd);if(h.children?.length){const d=el('details');d.append(el('summary',`同源其他单元（${h.children.length}）`));for(const child of h.children){const x=el('button',`${metaText(child)} · ${child.score.toFixed(4)}`);x.onclick=()=>guarded(()=>detail(child,qid));d.append(x)}b.append(d)}if(!$('#detail').open)$('#detail').showModal()}
$('#closeDetail').onclick=()=>$('#detail').close();$('#detail').onclick=e=>{if(e.target===$('#detail'))$('#detail').close()};
$('#searchForm').onsubmit=e=>{e.preventDefault();guarded(async()=>{const b=$('#searchButton');b.disabled=true;b.textContent='正在编码与检索…';try{const r=await api('search',{text:$('#query').value,image_asset:imageAsset,dataset:$('#searchDataset').value,kind:$('#kind').value,k:+$('#topk').value,dimension:+$('#dimension').value,aggregate:$('#aggregate').checked,exclude_self:$('#exclude').checked});queryId=r.id;$('#results').replaceChildren(...r.results.map(h=>card(h)));$('#empty').hidden=!!r.results.length;$('#empty').textContent='此数据集或类型下没有可检索单元，请先导入文件。';$('#resultTitle').textContent=`找到 ${r.results.length} 项结果`;$('#timing').textContent=`排队 ${(r.timings.queue_s*1000).toFixed(0)} ms · 预处理 ${(r.timings.preprocess_s*1000).toFixed(0)} ms · 编码 ${(r.timings.embedding_s*1000).toFixed(0)} ms · 检索 ${(r.timings.retrieval_s*1000).toFixed(0)} ms · 总计 ${(r.timings.response_total_s*1000).toFixed(0)} ms`;$('#resultNotice').textContent=r.notice}finally{b.disabled=false;b.textContent='开始检索 →'}})};
$('#createDataset').onclick=()=>guarded(async()=>{const d=await api('datasets',{name:$('#datasetName').value});await datasets(d.id);await loadAssets();$('#datasetName').value='';toast('数据集已创建')});$('#dataDataset').onchange=()=>guarded(loadAssets);
$('#serverImport').onclick=()=>guarded(async()=>{const r=await api('import-directory',{dataset:$('#dataDataset').value,path:$('#serverPath').value});toast(`已登记 ${r.files.filter(x=>!x.error).length} 项；${r.files.filter(x=>x.error).length} 项拒绝`);await loadAssets()});
$$('[data-control]').forEach(b=>b.onclick=()=>guarded(async()=>{await api('control',{dataset:$('#dataDataset').value,action:b.dataset.control});await loadAssets();toast('操作已登记；正在编码的单元将在安全边界结束')}));
$('#jointCreate').onclick=()=>guarded(async()=>{await api('joint-candidate',{dataset:$('#dataDataset').value,image_asset:$('#jointAsset').value.trim(),text:$('#jointText').value});await loadAssets();toast('图文联合候选已排队')});
async function loadAssets(){const rows=await api('assets?dataset='+encodeURIComponent($('#dataDataset').value));$('#assetTitle').textContent=`文件与队列 · ${rows.length} 项`;const counts={};rows.forEach(x=>counts[x.status]=(counts[x.status]||0)+1);$('#assetStats').textContent=Object.entries(counts).map(([k,v])=>`${labels[k]||k} ${v}`).join(' · ')||'还没有文件';$('#assets').replaceChildren(...rows.map(a=>{const r=el('tr');const name=el('td',a.name);name.title=a.id;r.append(name);const s=el('td');s.append(el('span',labels[a.status]||a.status,'status '+(a.status==='failed'?'failed':'')));r.append(s,el('td',a.units),el('td',(a.bytes/1024).toFixed(1)+' KB'),el('td',a.error||'—'));return r}))}
const types={text_image:'文搜图',image_image:'图搜图',joint_image:'图文搜图',text_pdf:'文搜 PDF',text_video:'文搜视频',text_text:'文搜文字'};
function renderMetrics(){const rows=metrics?.summary.filter(x=>x.level===$('#evalLevel').value)||[];$('#metrics').replaceChildren(...rows.map(x=>{const r=el('tr');for(const k of ['split','type','dimension','n','Hit@1','Hit@5','Hit@10','Recall@10','MRR'])r.append(el('td',k==='type'?types[x[k]]:typeof x[k]==='number'&&!['dimension','n'].includes(k)?x[k].toFixed(3):x[k]));return r}))}
async function loadEval(){const r=await api('benchmark');metrics=r.metrics;$('#evalState').textContent=r.job.state==='running'?'评测正在运行…':r.job.state==='failed'?'评测失败：'+r.job.error:metrics?'已完成 · '+metrics.run_id:'NOT_RUN · 尚未运行';$('#runBenchmark').disabled=r.job.state==='running';$('#downloads').hidden=!metrics;if(metrics){$('#evalStats').replaceChildren(...[[metrics.source_files,'源文件'],[metrics.units,'检索单元'],[metrics.queries,'固定查询'],[metrics.failures.length,'运行失败']].map(([v,t])=>{const d=el('div',undefined,'stat');d.append(el('strong',v),el('span',t));return d}));renderMetrics()}}
$('#evalLevel').onchange=renderMetrics;$('#runBenchmark').onclick=()=>guarded(async()=>{await api('benchmark',{});await loadEval();toast('固定评测已开始，使用当前单一模型 worker')});
$('#loadQueries').onclick=()=>guarded(async()=>{const r=await fetch('/api/report/per_query_results.jsonl');if(!r.ok)throw Error('评测尚未完成');const rows=(await r.text()).trim().split('\n').map(JSON.parse).filter(x=>x.dimension===4096&&x.level==='file'||x.status==='FAILED');$('#queryResults').replaceChildren(...rows.map(x=>{const d=el('details',undefined,'queryrow');d.append(el('summary',`${x.query} · ${x.text||types[x.type]} · ${x.status==='FAILED'?'失败：'+x.error:x.no_match?'无匹配题（未启用拒识阈值）':'Hit@1 '+x.metrics?.['Hit@1']}`));d.addEventListener('toggle',()=>{if(d.open&&!d.dataset.loaded){d.dataset.loaded='1';const c=el('div',undefined,'cards');c.append(...(x.top_k||[]).map(h=>card(h,x.query)));d.append(c)} });return d}))});
setInterval(()=>{if(authenticated)guarded(async()=>{await status();if(currentTab==='data')await loadAssets();if(currentTab==='eval')await loadEval()})},4000);
api('status').then(enter).catch(()=>{$('#health').textContent='需要登录'});
